async function addTestHarvest(excel) {
  const sheet = excel.workbook.worksheets.getItem("Harvests")
  const usedRange = sheet.getUsedRange()
  usedRange.load("rowCount")
  await excel.sync()
  const newRow = sheet.getRangeByIndexes(usedRange.rowCount, 0, 1, 5)
  newRow.values = [["2027-08-20", "B8", "Squash", 1.5, "test@example.com"]]
  await excel.sync()
  Jade.print(`Wrote row ${usedRange.rowCount + 1}`, "Test harvest")
  Jade.open_output()
}
